    "difficulty": 2,
    "stem": "中华苏维埃共和国实行的各级工农兵代表大会制度。",
    "source": {
      "kind": "exam",
      "year": "2410"
    },
    "referenceAnswer": "中华苏维埃共和国实行各级工农兵代表大会制度。先由苏维埃共和国公民直接选举产生乡工农兵代表大会代表，召开乡工农兵代表大会，选举产生乡苏维埃政府组成人员；在此基础上，逐级召开区、县、省和全国工农兵代表大会，选举产生区、县、省和全国苏维埃政府。各级苏维埃政府广泛吸收工农群众代表参加政权管理，行使当家作主的权利。"
