    "stem": "1912年建立的中华民国临时政府的性质。",
    "source": {
      "kind": "chapter_exercise"
    },
    "referenceAnswer": "它是一个资产阶级共和国性质的革命政权。\n1、在人员构成上，资产阶级革命派控制着政权。\n2、在实行的各项政策措施上，集中体现了中国民族资产阶级的愿望和利益，也一定程度上符合广大中国人民的利益。"
