    "referenceAnswer": "封建统治阶级中的部分成员如奕、曾国藩、李鸿章、左宗棠、张之洞、刘坤一等，主张学习西方的武器装备和科学技术，以“自强”、“求富”为目标，兴办洋务。这些官员被称为洋务派。"
