    "stem": "抗战初期国民党实行的若干有利于抗战的政策。国民参政会的成立。中国民主政团同盟的成立。中国共产党的成立民主联合政府的主张。国民政府军事委员会政治部第三厅领导组织的抗日文化工作。",
