    "chapter": "第七章",
    "difficulty": 2,
    "stem": "主要民主党派：中国国民党革命委员会(简称“民革”)；中国民主同盟(简称“民盟”)；中国民主建国会(简称“民建”)，组成人员主要是知识界和实业界的中上层人士；中国民主促进会(简称“民进”)，组成人员一部分是文化、教育、出版工作者，另一部分是上海工商界爱国人士；中国农工民主党(亦称“第三党”)；中国致公党；九三学社；台湾民主自治同盟(简称“台盟”)。",
