    "referenceAnswer": "中共十六届三中全会正式提出科学发展观。科学发展观，第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。中共十六届六中全会通过《关于构建社会主义和谐社会若干重大问题的决定》。推进经济又好又快发展，促进社会全面进步。坚持走和平发展的道路。加强党的执政能力建设和先进性建设，开展保持共产党员先进性教育活动。"
